/*
 * USB VFS 板级配置宏 (vfs/usb) — 中间件默认值 + 板级覆盖入口
 * 覆盖方式: 改本文件 或 编译 -D<NAME>=<N>; 未覆盖走默认。
 */
#ifndef BOARD_DEFINE_USB_H
#define BOARD_DEFINE_USB_H

/* host 池 = DTS "usb-otg-host" 节点数 (缺省 1) */
#ifndef DTC_GEN_COUNT_USB_OTG_HOST
#define DTC_GEN_COUNT_USB_OTG_HOST 1
#endif
#ifndef USB_VFS_PRIV_COUNT
#define USB_VFS_PRIV_COUNT DTC_GEN_COUNT_USB_OTG_HOST
#endif

/* client 池 = CDC-ACM + CDC-ECM + HID 节点数之和 (缺省各 1) */
#ifndef DTC_GEN_COUNT_HETEROGENEOUS_USB_CDC_ACM
#define DTC_GEN_COUNT_HETEROGENEOUS_USB_CDC_ACM 1
#endif
#ifndef DTC_GEN_COUNT_HETEROGENEOUS_USB_CDC_ECM
#define DTC_GEN_COUNT_HETEROGENEOUS_USB_CDC_ECM 1
#endif
#ifndef DTC_GEN_COUNT_HETEROGENEOUS_USB_HID
#define DTC_GEN_COUNT_HETEROGENEOUS_USB_HID 1
#endif
#ifndef USB_VFS_CLIENT_COUNT
#define USB_VFS_CLIENT_COUNT \
    (DTC_GEN_COUNT_HETEROGENEOUS_USB_CDC_ACM + DTC_GEN_COUNT_HETEROGENEOUS_USB_CDC_ECM + \
     DTC_GEN_COUNT_HETEROGENEOUS_USB_HID)
#endif

#endif /* BOARD_DEFINE_USB_H */
